import { useCallback, useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  analyzeCode,
  createDocument,
  deleteDocument,
  fetchDocument,
  fetchDocuments,
  updateDocument,
} from '../api';

const QUICK_START_BLUEPRINTS = [
  {
    id: 'bubble-sort',
    title: 'Bubble Sort',
    description: 'Nested loops · O(n²) time benchmark',
    content: `def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
    return arr
`,
  },
  {
    id: 'binary-search',
    title: 'Binary Search',
    description: 'Halving boundaries · O(log n) time benchmark',
    content: `def binary_search(arr, target):
    low = 0
    high = len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1
`,
  },
  {
    id: 'recursive-addition',
    title: 'Recursive Addition',
    description: 'Linear recursion · O(n) time & stack space',
    content: `def recursive_add(n):
    if n <= 0:
        return 0
    return n + recursive_add(n - 1)
`,
  },
];

function operationsForClass(timeClass, n) {
  if (timeClass === 'O(1)') return 1;
  if (timeClass === 'O(log n)') return Math.max(1, Math.floor(Math.log2(Math.max(n, 2))));
  if (timeClass === 'O(n)') return n;
  if (timeClass === 'O(n log n)') return Math.max(1, Math.floor(n * Math.log2(Math.max(n, 2))));
  if (timeClass === 'O(n²)') return n * n;
  if (timeClass === 'O(n³)') return n ** 3;
  return n;
}

function buildIdealCoordinates(idealClass, userCoordinates) {
  if (!userCoordinates || userCoordinates.length === 0) return [];
  return userCoordinates.map((point) => ({
    input_size: point.input_size,
    operations: operationsForClass(idealClass, point.input_size),
  }));
}

function ComplexityGraph({ userCoordinates, idealCoordinates, userLabel, idealLabel }) {
  if (!userCoordinates || userCoordinates.length === 0) {
    return null;
  }

  const padding = { top: 28, right: 28, bottom: 44, left: 56 };
  const width = 600;
  const height = 240;
  const chartWidth = width - padding.left - padding.right;
  const chartHeight = height - padding.top - padding.bottom;

  const allPoints = [...userCoordinates, ...(idealCoordinates || [])];
  const maxInput = Math.max(...allPoints.map((p) => p.input_size));
  const maxOps = Math.max(...allPoints.map((p) => p.operations), 1);

  const scaleX = (inputSize) => padding.left + (inputSize / maxInput) * chartWidth;
  const scaleY = (operations) =>
    padding.top + chartHeight - (operations / maxOps) * chartHeight;

  const toPolyline = (coords) =>
    coords.map((p) => `${scaleX(p.input_size)},${scaleY(p.operations)}`).join(' ');

  const yTicks = [0, Math.round(maxOps / 2), maxOps];
  const xTicks = userCoordinates.map((p) => p.input_size);

  return (
    <div className="graph-container">
      <svg
        className="graph-svg"
        viewBox={`0 0 ${width} ${height}`}
        role="img"
        aria-label="User code vs ideal efficiency benchmark chart"
      >
        <line
          x1={padding.left}
          y1={padding.top + chartHeight}
          x2={padding.left + chartWidth}
          y2={padding.top + chartHeight}
          stroke="#3a3a42"
          strokeWidth="1"
        />
        <line
          x1={padding.left}
          y1={padding.top}
          x2={padding.left}
          y2={padding.top + chartHeight}
          stroke="#3a3a42"
          strokeWidth="1"
        />
        {yTicks.map((tick) => (
          <g key={`y-${tick}`}>
            <line
              x1={padding.left}
              y1={scaleY(tick)}
              x2={padding.left + chartWidth}
              y2={scaleY(tick)}
              stroke="#2a2a30"
              strokeWidth="1"
              strokeDasharray="4 4"
            />
            <text
              x={padding.left - 8}
              y={scaleY(tick) + 4}
              textAnchor="end"
              fill="#8b8b96"
              fontSize="10"
            >
              {tick}
            </text>
          </g>
        ))}
        {xTicks.map((tick) => (
          <text
            key={`x-${tick}`}
            x={scaleX(tick)}
            y={padding.top + chartHeight + 22}
            textAnchor="middle"
            fill="#8b8b96"
            fontSize="10"
          >
            {tick}
          </text>
        ))}
        {idealCoordinates && idealCoordinates.length > 0 && (
          <>
            <polyline
              points={toPolyline(idealCoordinates)}
              fill="none"
              stroke="#6ee7b7"
              strokeWidth="2"
              strokeDasharray="6 4"
              strokeLinejoin="round"
            />
            {idealCoordinates.map((p) => (
              <circle
                key={`ideal-${p.input_size}`}
                cx={scaleX(p.input_size)}
                cy={scaleY(p.operations)}
                r="4"
                fill="#6ee7b7"
                stroke="#121214"
                strokeWidth="1.5"
              />
            ))}
          </>
        )}
        <polyline
          points={toPolyline(userCoordinates)}
          fill="none"
          stroke="#00adb5"
          strokeWidth="2.5"
          strokeLinejoin="round"
        />
        {userCoordinates.map((p) => (
          <circle
            key={`user-${p.input_size}`}
            cx={scaleX(p.input_size)}
            cy={scaleY(p.operations)}
            r="5"
            fill="#00adb5"
            stroke="#121214"
            strokeWidth="2"
          />
        ))}
        <text
          x={padding.left + chartWidth / 2}
          y={height - 8}
          textAnchor="middle"
          fill="#8b8b96"
          fontSize="11"
        >
          Input size (n)
        </text>
        <text
          x={16}
          y={padding.top + chartHeight / 2}
          textAnchor="middle"
          fill="#8b8b96"
          fontSize="11"
          transform={`rotate(-90, 16, ${padding.top + chartHeight / 2})`}
        >
          Operations
        </text>
      </svg>
      <div className="graph-legend graph-legend-dual">
        <span className="legend-user">
          <span className="legend-swatch legend-swatch-user" />
          {userLabel || 'Your code'}
        </span>
        <span className="legend-ideal">
          <span className="legend-swatch legend-swatch-ideal" />
          {idealLabel || 'Ideal efficiency baseline'}
        </span>
      </div>
    </div>
  );
}

function Dashboard() {
  const navigate = useNavigate();
  const titleInputRef = useRef(null);
  const [documents, setDocuments] = useState([]);
  const [selectedDoc, setSelectedDoc] = useState(null);
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [analysis, setAnalysis] = useState(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [error, setError] = useState('');
  const [status, setStatus] = useState('');
  const [syntaxError, setSyntaxError] = useState('');

  const username = localStorage.getItem('algospace_username') || 'Developer';

  const loadDocuments = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const data = await fetchDocuments();
      const list = Array.isArray(data) ? data : [];
      setDocuments(list);
    } catch (err) {
      setError(err.message || 'Failed to load documents.');
      setDocuments([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadDocuments();
  }, [loadDocuments]);

  const focusTitleInput = () => {
    requestAnimationFrame(() => {
      if (titleInputRef.current) {
        titleInputRef.current.focus();
        titleInputRef.current.select();
      }
    });
  };

  const applyDocument = (doc) => {
    setSelectedDoc(doc.id);
    setTitle(doc.title);
    setContent(doc.content || '');
    setAnalysis(null);
    setSyntaxError('');
  };

  const selectDocument = async (id) => {
    setError('');
    setStatus('');
    setAnalysis(null);
    setSyntaxError('');
    try {
      const doc = await fetchDocument(id);
      applyDocument(doc);
    } catch (err) {
      setError(err.message || 'Failed to load document.');
    }
  };

  const handleNewPage = async () => {
    setError('');
    setStatus('');
    setAnalysis(null);
    setSyntaxError('');
    try {
      const doc = await createDocument({
        title: 'Untitled',
        content: '',
      });
      await loadDocuments();
      applyDocument(doc);
      setStatus('New page created — name your file below.');
      focusTitleInput();
    } catch (err) {
      setError(err.message || 'Failed to create document.');
    }
  };

  const handleBlueprint = async (blueprint) => {
    setError('');
    setStatus('');
    setAnalysis(null);
    setSyntaxError('');
    try {
      const doc = await createDocument({
        title: blueprint.title,
        content: blueprint.content,
      });
      await loadDocuments();
      applyDocument(doc);
      setStatus(`${blueprint.title} blueprint loaded.`);
      focusTitleInput();
    } catch (err) {
      setError(err.message || 'Failed to create blueprint document.');
    }
  };

  const handleSave = async () => {
    if (!selectedDoc) {
      setError('Select or create a page before saving.');
      return;
    }
    const trimmedTitle = title.trim();
    if (!trimmedTitle) {
      setError('Title cannot be empty.');
      return;
    }
    setSaving(true);
    setError('');
    setStatus('');
    try {
      await updateDocument(selectedDoc, {
        title: trimmedTitle,
        content,
        ...(analysis
          ? {
              time_complexity: analysis.time_complexity,
              space_complexity: analysis.space_complexity,
              justification: analysis.justification,
            }
          : {}),
      });
      await loadDocuments();
      setStatus('Page saved.');
    } catch (err) {
      setError(err.message || 'Failed to save document.');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (!selectedDoc) {
      setError('No page selected to delete.');
      return;
    }
    setError('');
    setStatus('');
    try {
      await deleteDocument(selectedDoc);
      setSelectedDoc(null);
      setTitle('');
      setContent('');
      setAnalysis(null);
      setSyntaxError('');
      await loadDocuments();
      setStatus('Page deleted.');
    } catch (err) {
      setError(err.message || 'Failed to delete document.');
    }
  };

  const handleAnalyze = async () => {
    const trimmed = content.trim();
    if (!trimmed) {
      setError('Cannot analyze empty code. Enter Python in the editor first.');
      setAnalysis(null);
      setSyntaxError('');
      return;
    }
    setAnalyzing(true);
    setError('');
    setStatus('');
    setSyntaxError('');
    try {
      const result = await analyzeCode(trimmed);
      const idealCoords =
        result.ideal_graph_coordinates ||
        buildIdealCoordinates(
          result.ideal_time_complexity,
          result.graph_coordinates
        );
      setAnalysis({
        ...result,
        ideal_graph_coordinates: idealCoords,
      });
      setStatus('AST complexity analysis complete.');
    } catch (err) {
      setAnalysis(null);
      const isSyntax =
        err.status === 400 &&
        (err.message || '').toLowerCase().includes('syntax error');
      if (isSyntax) {
        setSyntaxError(
          err.message ||
            'Syntax Error: Invalid Python structure or indentation detected.'
        );
        setError('');
      } else {
        setSyntaxError('');
        setError(err.message || 'Analysis request failed.');
      }
    } finally {
      setAnalyzing(false);
    }
  };

  const handleContentChange = (e) => {
    setContent(e.target.value);
    if (syntaxError) {
      setSyntaxError('');
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('algospace_token');
    localStorage.removeItem('algospace_username');
    navigate('/auth');
  };

  const idealCoordinates =
    analysis &&
    (analysis.ideal_graph_coordinates ||
      buildIdealCoordinates(
        analysis.ideal_time_complexity,
        analysis.graph_coordinates
      ));

  return (
    <div className="dashboard">
      <header className="dashboard-header">
        <h1>AlgoSpace</h1>
        <div className="dashboard-header-actions">
          <span className="user-info">Signed in as {username}</span>
          <button type="button" className="btn btn-danger" onClick={handleLogout}>
            Log out
          </button>
        </div>
      </header>

      <div className="dashboard-body">
        <aside className="sidebar">
          <div className="sidebar-header">
            <h2>Pages</h2>
            <button type="button" className="btn btn-primary" onClick={handleNewPage}>
              + New Page
            </button>
          </div>
          {error && !syntaxError && (
            <div className="alert alert-error sidebar-alert">{error}</div>
          )}
          <ul className="file-list">
            {loading && <li className="empty-state">Loading pages...</li>}
            {!loading && documents.length === 0 && (
              <li className="empty-state">No pages yet. Use + New Page or a blueprint.</li>
            )}
            {!loading &&
              documents.map((doc) => (
                <li key={doc.id}>
                  <button
                    type="button"
                    className={selectedDoc === doc.id ? 'active' : ''}
                    onClick={() => selectDocument(doc.id)}
                  >
                    {doc.title || 'Untitled'}
                  </button>
                </li>
              ))}
          </ul>
        </aside>

        <main className="workspace">
          {selectedDoc ? (
            <>
              <div className="workspace-toolbar">
                <input
                  ref={titleInputRef}
                  type="text"
                  className="title-input"
                  placeholder="Page title"
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                />
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={handleSave}
                  disabled={saving}
                >
                  {saving ? 'Saving...' : 'Save'}
                </button>
                <button
                  type="button"
                  className="btn btn-primary"
                  onClick={handleAnalyze}
                  disabled={analyzing}
                >
                  {analyzing ? 'Analyzing...' : 'Analyze Complexity'}
                </button>
                <button type="button" className="btn btn-danger" onClick={handleDelete}>
                  Delete
                </button>
                {status && <span className="status-message">{status}</span>}
              </div>

              <div
                className={`editor-area profiler-workspace${
                  syntaxError ? ' profiler-workspace-syntax-error' : ''
                }`}
              >
                {syntaxError && (
                  <div className="syntax-inline-error" role="alert">
                    {syntaxError}
                  </div>
                )}
                <textarea
                  placeholder="Write valid Python code here for AST analysis..."
                  value={content}
                  onChange={handleContentChange}
                />

                {analysis && (
                  <section className="analysis-panel">
                    <h3>Complexity Analysis</h3>
                    <div className="complexity-meta">
                      <div>
                        <span>Time</span>
                        <strong>{analysis.time_complexity}</strong>
                      </div>
                      <div>
                        <span>Space</span>
                        <strong>{analysis.space_complexity}</strong>
                      </div>
                      {analysis.ideal_time_complexity && (
                        <div>
                          <span>Ideal target</span>
                          <strong>{analysis.ideal_time_complexity}</strong>
                        </div>
                      )}
                    </div>
                    <p className="justification-text">{analysis.justification}</p>
                    <ComplexityGraph
                      userCoordinates={analysis.graph_coordinates}
                      idealCoordinates={idealCoordinates}
                      userLabel={`Your code (${analysis.time_complexity})`}
                      idealLabel={`Ideal baseline (${analysis.ideal_time_complexity || 'O(1)'})`}
                    />
                  </section>
                )}
              </div>
            </>
          ) : (
            <div className="empty-dashboard">
              <div className="empty-dashboard-hero">
                <h2>Welcome to your workspace</h2>
                <p>
                  Select a page from the sidebar, create a new page, or launch a
                  Quick-Start Blueprint to begin profiling Python algorithms with
                  static AST analysis.
                </p>
                <button type="button" className="btn btn-primary" onClick={handleNewPage}>
                  + New Page
                </button>
              </div>
              <div className="blueprint-grid">
                <h3>Quick-Start Blueprints</h3>
                <div className="blueprint-cards">
                  {QUICK_START_BLUEPRINTS.map((bp) => (
                    <button
                      key={bp.id}
                      type="button"
                      className="blueprint-card"
                      onClick={() => handleBlueprint(bp)}
                    >
                      <span className="blueprint-card-title">{bp.title}</span>
                      <span className="blueprint-card-desc">{bp.description}</span>
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}
        </main>
      </div>
    </div>
  );
}

export default Dashboard;
